{
  "name": "opencode-cache-coach",
  "version": "0.7.0",
  "description": "OpenCode plugin that shows whether a session's prompt cache is still warm, suggests cheaper habits when a costly pattern shows up, and warns when cache misses persist",
  "author": {
    "name": "Pedro Pombeiro",
    "email": "pedropombeiro@users.noreply.github.com"
  },
  "type": "module",
  "exports": {
    ".": {
      "default": "./dist/index.js"
    },
    "./tui": {
      "default": "./dist/tui.js"
    },
    "./gui-experimental": {
      "default": "./dist/gui-experimental.cjs"
    }
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/pedropombeiro/opencode-plugins.git",
    "directory": "packages/cache-coach"
  },
  "publishConfig": {
    "access": "public"
  },
  "files": [
    "dist"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "prompt-cache",
    "cost",
    "tokens"
  ],
  "license": "MIT",
  "peerDependencies": {
    "@opencode/plugin": "^2.2.0",
    "@opentui/core": ">=0.7.0",
    "@opentui/solid": ">=0.7.0",
    "solid-js": ">=1.9.0"
  }
}

// @bun
// packages/cache-coach/src/notice.ts
var NOTICE_TEXT = "[cache-coach: a prompt cache notice for the user. Ignore it.]";
var isNotice = (message) => {
  if (message.role !== "user" || message.content.length !== 1)
    return false;
  const part = message.content[0];
  return part?.type === "text" && part.text === NOTICE_TEXT;
};
var withoutNotices = (messages) => messages.filter((message) => !isNotice(message));

// packages/cache-coach/src/index.ts
var src_default = {
  id: "opencode-cache-coach",
  async setup(ctx) {
    for (const kind of ["context", "generate", "compaction", "title"])
      await ctx.session.hook(kind, (event) => {
        event.messages = withoutNotices(event.messages);
      });
  }
};
export {
  src_default as default
};
